mapper.select:
SELECT id, tenant_id, product_key, device_name, display_name, device_type, secret, status, protocol_type, protocol_version, created_at, updated_at
FROM iot_device
WHERE product_key = #{productKey}
  AND device_name = #{deviceName}

mapper.update:
UPDATE iot_device
SET display_name = #{displayName},
    updated_at = CURRENT_TIMESTAMP
WHERE product_key = #{productKey}
  AND device_name = #{deviceName}

UPDATE iot_device
SET status = #{status},
    updated_at = CURRENT_TIMESTAMP
WHERE product_key = #{productKey}
  AND device_name = #{deviceName}

UPDATE iot_device
SET secret = #{secret},
    updated_at = CURRENT_TIMESTAMP
WHERE product_key = #{productKey}
  AND device_name = #{deviceName}

mapper.delete:
DELETE FROM iot_device
WHERE product_key = #{productKey}
  AND device_name = #{deviceName}
